def main():
    with open(os.path.join(BASE, "payment_matrix_raw.csv"), "w",
              encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=FIELDS, extrasaction="ignore")
        w.writeheader()
        for r in ROWS:
            w.writerow({k: r.get(k, "") for k in FIELDS})
    print(f"wrote {len(ROWS)} rows -> payment_matrix_raw.csv")

if __name__ == "__main__":
    main()
